def decode(s):
    result = []
    i = 0
    while i < len(s):
        char = s[i]
        i += 1
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1
        run = int(s[i:j]) if j > i else 1
        result.append(char * run)
        i = j
    return ''.join(result)
